/**
 * Private object storage for evidence and uploads (R1-04, R2-01). Never public: files reach
 * browsers only through the API after an authorisation check (ADR-010).
 */
export interface ObjectStore {
  put: (key: string, body: Buffer, contentType: string) => Promise<void>;
  get: (key: string) => Promise<Buffer>;
  remove: (key: string) => Promise<void>;
  /** Readiness probe. */
  ping: () => Promise<void>;
}

/** Keys are generated by us (random UUID paths); anything else is refused, so no traversal. */
// eslint-disable-next-line security/detect-unsafe-regex -- every quantifier is bounded (≤64 chars, ≤4 segments) and segments can't overlap across '/', so no catastrophic backtracking
const KEY = /^[a-z0-9-]{1,64}(\/[a-z0-9-]{1,64}){0,4}$/u;

export function assertSafeKey(key: string): void {
  if (!KEY.test(key)) throw new TypeError('Invalid object key');
}
